/**
 * Roboverse X — Level 2 problem statements (PS1: Task 1–2, PS2: Task 3–4 with 4 cards).
 * Geometry lives in tasks.data.json, generated by packages/rvx-sim/tools/level2_tasks.py
 * (the same file the Python tests and the future server judge use).
 *
 *   rvx.setTask(getTask("ps1-t1-reach-goal"))      // configure arena + evaluation
 *   const s = useRvx(); s.evaluation?.checks        // auto-evaluation after each run
 */
import { scoreSegments, type Target } from "@/sim/score";
import type { Segment } from "@/sim/engine";
import type { WorkerRunResult } from "./python-runtime";
import type { ProgramData } from "./sim-controller";
import data from "./tasks.data.json";

export type TaskCheck =
  | "goal_reached" | "stopped" | "goal_log" | "closed_loop" | "no_teleport"
  | "guards_spawned" | "guard_clearance" | "shape_match" | "one_stroke" | "pen_up_teleport"
  | `distinct_colours:${number}`;

export type ArenaTask = {
  id: string;
  ps: 1 | 2;
  task: 1 | 2 | 3 | 4;
  card: 1 | 2 | 3 | 4 | null;
  title: string;
  summary: string;
  descriptionMd: string;
  start: { x: number; y: number; theta: number };
  goal: { x: number; y: number; tolerance: number } | null;
  guards: { safeRadius: number; spawn: { name: string; x: number; y: number }[] } | null;
  target: (Target & { tolerance: number }) | null;
  tolerance: number;
  passThreshold: number;
  rules: { allow_teleport: boolean; teleport_pen_up_only?: boolean };
  maxSimSec: number;
  checks: TaskCheck[];
  starterCode: string;
};

export type CheckResult = { id: string; label: string; ok: boolean; detail: string };
/** `code` is the exact program that produced this evaluation (submit only if the editor still holds it). */
export type TaskEvaluation = { taskId: string; passed: boolean; score: number | null; checks: CheckResult[]; at: number; code: string };

export const TASKS = data as unknown as ArenaTask[];
export const getTask = (id: string): ArenaTask => {
  const t = TASKS.find((x) => x.id === id);
  if (!t) throw new Error(`unknown task ${id}`);
  return t;
};
/** The four Task-4 cards, in card order. */
export const TASK4_CARDS = TASKS.filter((t) => t.task === 4).sort((a, b) => (a.card ?? 0) - (b.card ?? 0));

/**
 * Task 4 "you draw the card you are handed": a stable card per participant
 * (same participant id → same card; ids spread evenly over the 4 cards).
 * Organisers can override by passing an explicit card number instead.
 */
export function assignCard(participantId: string): ArenaTask {
  let h = 2166136261;
  for (const ch of participantId.trim().toLowerCase()) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  return TASK4_CARDS[(h >>> 0) % TASK4_CARDS.length];
}

/** Tasks in portal order: PS1 (Task 1 → Task 2), PS2 (Task 3, assigned Task 4 card). */
export function tasksFor(participantId: string): ArenaTask[] {
  return [getTask("ps1-t1-reach-goal"), getTask("ps1-t2-dodge-guards"), getTask("ps2-t3-basic-shapes"), assignCard(participantId)];
}

const segLen = (s: Segment) => Math.hypot(s[3] - s[1], s[4] - s[2]);

/** Mirror of packages/rvx-sim/tools/level2_eval.py — keep both in sync. */
export function evaluateTask(task: ArenaTask, run: ProgramData, result: WorkerRunResult | null, code: string): TaskEvaluation {
  const checks: CheckResult[] = [];
  const add = (id: string, label: string, ok: boolean, detail = "") => checks.push({ id, label, ok, detail });
  const finished = result?.status === "finished";
  const teleports = run.events.filter((e) => e.type === "teleport");
  let score: number | null = null;

  for (const c of task.checks) {
    const [name, arg] = c.split(":");
    switch (name) {
      case "goal_reached": {
        const g = task.goal!;
        const d = Math.hypot(run.finalPose.x - g.x, run.finalPose.y - g.y);
        add(c, `Target reached (≤ ${g.tolerance})`, finished && d <= g.tolerance, `final distance ${d.toFixed(3)}`);
        break;
      }
      case "stopped":
        // a finished run ends only once turtle1 is at rest (the last Twist is drained)
        add(c, "Stopped at the end", finished, finished ? "" : result?.error ?? result?.status ?? "not finished");
        break;
      case "goal_log":
        add(c, 'Logged "Goal reached"', run.logs.some((l) => /goal reached/i.test(l.msg)));
        break;
      case "closed_loop":
        add(c, "Closed loop (/turtle1/pose → /turtle1/cmd_vel)", code.includes("turtle1/pose") && code.includes("cmd_vel"));
        break;
      case "no_teleport":
        add(c, "No teleport", teleports.length === 0, teleports.length ? `${teleports.length} teleport call(s)` : "");
        break;
      case "guards_spawned": {
        const got = new Map(run.guardsSpawned.map((g) => [g.name, g]));
        const missing = task.guards!.spawn.filter((g) => {
          const s = got.get(g.name);
          return !s || Math.hypot(s.x - g.x, s.y - g.y) > 0.05;
        }).map((g) => g.name);
        add(c, "Spawned obstacle1–3 at the given positions", missing.length === 0, missing.length ? `missing/misplaced: ${missing.join(", ")}` : "");
        break;
      }
      case "guard_clearance": {
        const r = task.guards!.safeRadius;
        const cg = run.closestGuard;
        const allSpawned = task.guards!.spawn.every((g) => run.guardsSpawned.some((s) => s.name === g.name));
        add(c, `Never within ${r.toFixed(1)} of a guard`, !!cg && allSpawned && cg.distance >= r, cg ? `closest ${cg.distance.toFixed(3)} (${cg.name})` : "no guards spawned");
        break;
      }
      case "shape_match": {
        const res = result?.preview ?? scoreSegments(run.visibleSegments, task.target!, { tolerance: task.tolerance });
        score = res.score;
        add(c, `Shape match ≥ ${task.passThreshold}%`, finished && res.score >= task.passThreshold,
          `${res.score.toFixed(2)}% (recall ${res.recall.toFixed(3)}, precision ${res.precision.toFixed(3)})`);
        break;
      }
      case "distinct_colours": {
        const need = Number(arg ?? 1);
        const n = new Set(run.visibleSegments.map((s) => `${s[5]},${s[6]},${s[7]}`)).size;
        add(c, `At least ${need} different colours`, n >= need, `${n} colour(s)`);
        break;
      }
      case "one_stroke": {
        const segs = run.visibleSegments;
        let strokes = 0;
        segs.forEach((s, i) => {
          if (i === 0 || Math.abs(segs[i - 1][3] - s[1]) > 1e-4 || Math.abs(segs[i - 1][4] - s[2]) > 1e-4) strokes++;
        });
        add(c, "One continuous stroke", strokes === 1, `${strokes} stroke(s)`);
        break;
      }
      case "pen_up_teleport": {
        const ticks = new Set(teleports.map((e) => e.tick));
        const bad = run.visibleSegments.filter((s) => ticks.has(s[0]) && segLen(s) > 0.2).length;
        add(c, "Pen up between shapes (no pen-down teleport)", bad === 0, bad ? `${bad} pen-down jump(s)` : "");
        break;
      }
      default:
        add(c, c, false, "unknown check");
    }
  }
  return { taskId: task.id, passed: checks.every((x) => x.ok), score, checks, at: typeof window === "undefined" ? 0 : Date.now(), code };
}

/** The task's checks with proper labels, all "waiting" — for the AUTO EVALUATION bar before the first run. */
export function pendingChecks(task: ArenaTask): CheckResult[] {
  const empty: ProgramData = {
    poses: [task.start.x, task.start.y, task.start.theta], segments: [], visibleSegments: [], clears: [], logs: [],
    events: [], guardsSpawned: [], closestGuard: null, finalPose: { ...task.start }, ticks: 0,
  };
  return evaluateTask(task, empty, null, "").checks.map((c) => ({ ...c, ok: false, detail: "waiting for run" }));
}
